import React, { useState } from 'react';
import HeroSection from './components/HeroSection';
import WhyYouSpecialSection from './components/WhyYouSpecialSection';
import BlockchainLoveSection from './components/BlockchainLoveSection';
import BigQuestionSection from './components/BigQuestionSection';
import SuccessOverlay from './components/SuccessOverlay';
import FloatingHearts from './components/FloatingHearts';

function App() {
  const [showSuccess, setShowSuccess] = useState(false);

  const handleYes = () => {
    setShowSuccess(true);
  };

  return (
    <div className="w-full min-h-screen bg-gradient-to-br from-cardano via-purple-100 to-love-light">
      <FloatingHearts />

      <HeroSection onYes={handleYes} />
      <WhyYouSpecialSection />
      <BlockchainLoveSection />
      <BigQuestionSection onYes={handleYes} />

      {showSuccess && <SuccessOverlay onClose={() => setShowSuccess(false)} />}
    </div>
  );
}

export default App;
